export function deepEquals(a, b) {
    return JSON.stringify(a) === JSON.stringify(b);
}

export function generateUniqueTitle(baseTitle, existingTitles) {
    const titleSet = new Set(existingTitles);
    if (!titleSet.has(baseTitle)) return baseTitle;
    const match = baseTitle.match(/^(.*)-(\d+)$/);
    const stem = match ? match[1] : baseTitle;
    let counter = match ? parseInt(match[2], 10) + 1 : 1;
    let candidate = `${stem}-${counter}`;
    while (titleSet.has(candidate)) {
        counter++;
        candidate = `${stem}-${counter}`;
    }
    return candidate;
}

cancelDelete() {
    if (this.deleteInProgress) return;
    this.showDeleteDialog = false;
}

async showClone() {
    if (Store.editor.hasChanges) {
        const confirmed = await this.promptDiscardChanges();
        if (!confirmed) return;
    }
    const fragments = Store.fragments.list.data.get() ?? [];
    const existingTitles = fragments.map((fs) => fs.get?.()?.title).filter(Boolean);
    this.titleClone = generateUniqueTitle(this.fragment.title, existingTitles);
    this.showCloneDialog = true;
    Store.showCloneDialog.set(true);
}

showCreateVariation() {
    this.showCreateVariationDialog = true;
}

cancelCreateVariation() {
    this.showCreateVariationDialog = false;
}

async confirmClone() {
    const osi = this.fragment.getFieldValue('osi', 0);
    if (this.fragment.model.path === CARD_MODEL_PATH && !this.osiClone && !osi) {
        showToast('Please select an offer', 'negative');
        return;
    }

    try {
        this.cloneInProgress = true;
        await this.repository.copyFragment(this.titleClone, this.osiClone, this.tagsClone);
        this.cancelClone();
    } catch (error) {
        console.error('Error cloning fragment:', error);
    } finally {
        this.cloneInProgress = false;
    }
}

cancelClone() {
    this.showCloneDialog = false;
    Store.showCloneDialog.set(false);
    this.titleClone = '';
    this.tagsClone = [];
    this.osiClone = null;
}

handleTagsChangeOnClone(e) {
    const value = e.target.getAttribute('value');
    this.tagsClone = value ? value.split(',') : [];
}

}

cancelClone() {
    this.showCloneDialog = false;
    Store.showCloneDialog.set(false);
    this.titleClone = '';
    this.tagsClone = [];
    this.osiClone = null;
    document.removeEventListener(EVENT_OST_OFFER_SELECT, this.#onOstSelectClone);
}

